</section></div></main><script>document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('[data-file-input]').forEach(input=>input.addEventListener('change',()=>{const label=input.closest('label').querySelector('[data-file-name]'),count=input.files.length;label.textContent=count?(count===1?input.files[0].name:`${count} archivos seleccionados`):(input.multiple?'Puedes seleccionar varias imágenes':'JPG, PNG o WebP · máximo 5 MB')}));const lightbox=document.getElementById('galleryLightbox');if(lightbox){const triggers=[...document.querySelectorAll('[data-lightbox-src]')],sources=[...new Set(triggers.map(trigger=>trigger.dataset.lightboxSrc))],image=lightbox.querySelector('[data-lightbox-image]');let current=0;const show=index=>{current=(index+sources.length)%sources.length;image.src=sources[current];lightbox.classList.remove('hidden');lightbox.classList.add('grid');document.body.style.overflow='hidden'};const close=()=>{lightbox.classList.add('hidden');lightbox.classList.remove('grid');document.body.style.overflow=''};triggers.forEach(trigger=>trigger.addEventListener('click',()=>show(sources.indexOf(trigger.dataset.lightboxSrc))));lightbox.querySelector('[data-lightbox-close]').addEventListener('click',close);lightbox.querySelector('[data-lightbox-prev]').addEventListener('click',()=>show(current-1));lightbox.querySelector('[data-lightbox-next]').addEventListener('click',()=>show(current+1));lightbox.addEventListener('click',event=>{if(event.target===lightbox)close()});document.addEventListener('keydown',event=>{if(lightbox.classList.contains('hidden'))return;if(event.key==='Escape')close();if(event.key==='ArrowLeft')show(current-1);if(event.key==='ArrowRight')show(current+1)})}const type=document.getElementById('listingType'),category=document.getElementById('businessCategory');if(type&&category){const filterCategories=()=>{[...category.options].forEach(option=>{option.hidden=option.dataset.type!==type.value;option.disabled=option.hidden});if(category.selectedOptions[0]?.disabled)category.value=''};type.addEventListener('change',filterCategories);filterCategories()}const box=document.getElementById('compactSchedule');if(!box)return;const second=document.getElementById('secondShiftEnabled'),secondFields=document.getElementById('secondShiftFields'),preset=document.getElementById('schedulePreset');const syncSecond=()=>secondFields.classList.toggle('hidden',!second.checked);const syncHidden=()=>{document.querySelectorAll('.schedule-day').forEach(day=>{const key=day.dataset.day,open=day.checked;document.querySelector(`[data-schedule=closed][data-day=${key}]`).value=open?'0':'1';document.querySelector(`[data-schedule=open1][data-day=${key}]`).value=open?document.getElementById('scheduleOpen1').value:'';document.querySelector(`[data-schedule=close1][data-day=${key}]`).value=open?document.getElementById('scheduleClose1').value:'';document.querySelector(`[data-schedule=open2][data-day=${key}]`).value=open&&second.checked?document.getElementById('scheduleOpen2').value:'';document.querySelector(`[data-schedule=close2][data-day=${key}]`).value=open&&second.checked?document.getElementById('scheduleClose2').value:''})};second.addEventListener('change',()=>{syncSecond();syncHidden()});box.querySelectorAll('input,select').forEach(control=>control.addEventListener('change',syncHidden));preset.addEventListener('change',()=>{const values={business:['08:00','18:00',false,'15:00','22:00'],office:['08:00','17:00',false,'15:00','22:00'],split:['08:00','12:00',true,'17:00','23:00'],always:['00:00','23:59',false,'15:00','22:00']}[preset.value];if(!values)return;['scheduleOpen1','scheduleClose1','scheduleOpen2','scheduleClose2'].forEach((id,index)=>document.getElementById(id).value=values[index+(index>1?1:0)]);second.checked=values[2];syncSecond();syncHidden()});box.closest('form').addEventListener('submit',syncHidden);syncSecond();syncHidden()})</script></x-marketplace-layout>
